let input = query;
if (typeof input === 'string') { try { input = JSON.parse(input); } catch (e) { input = {}; } }
const title = String(input.title || 'Summary');
const type = ['bar','line','pie','doughnut'].includes(input.chart_type) ? input.chart_type : 'bar';
const labels = String(input.labels || '').split(',').map(function (x) { return x.trim(); });
const values = String(input.values || '').split(',').map(function (x) { return Number(x.trim()); });
const unit = String(input.unit || '');
const cfg = {
  type: type,
  data: { labels: labels, datasets: [{ label: title + (unit ? ' (' + unit + ')' : ''), data: values }] },
  options: { plugins: { title: { display: true, text: title } } }
};
const url = 'https://quickchart.io/chart?w=800&h=450&bkg=white&c=' + encodeURIComponent(JSON.stringify(cfg));
return '![' + title + '](' + url + ')';
